import mathimport matplotlib.pyplot as pltimport turtle as timport timeimport keyboarddata1 = []data2 = []data3 = []data4 = []counter = 0Addition_OFF = 0Degree = 0Abstand = 0Faktor = 0Speed = 0Adittion = 0def TurtleSim(color):    global data1    global counter    global Degree    global Abstand    global Faktor    global Speed    global Adittion    rad: float = math.radians(Degree)    x_Start: float = math.sin(rad) * Abstand * -5    y_Start: float = math.cos(rad) * Abstand * -5    t.goto(0, 0)    t.setheading(0)    t.rt(90)    t.up()    t.fd(0)    t.down()    t.shape("circle")    t.shapesize(1.9)    t.color("blue")    t.stamp()    t.up()    t.goto(x_Start * -1, y_Start * -1)    t.down()    t.shape("circle")    t.shapesize(4.6)    t.width(3)    t.color(color)    while (keyboard.is_pressed("e") == False):        (xf, yf) = t.pos()        x: float = round(xf, 2)        y: float = round(yf, 2)  # -40        y_ball: float = round(yf, 2)        degree2 = (math.degrees(math.atan2(x, y)) * -1)        entfernung = 100 - (math.sqrt((y * y) + (x * x)) / 5)        Ball_ausr = (abs(degree2) * (80 / 180)) + 20        Faktor = (1 + (Multiplier * entfernung * Ball_ausr))        heading = degree2 * Faktor        t.setheading(heading - 90)        t.fd(Speed / 120)        if x < 10 and x > -10 and y < 10 and y > -10:            # t.shapesize(0.1)            break        else:            data1.append(degree2)            data2.append(heading)            data3.append(entfernung)    while (keyboard.is_pressed("e") == False):        time.sleep(0.0001)Speed = 500Abstand = 100Degree = 90Multiplier = 0.00012TurtleSim("green")Multiplier = 0.00012Degree = 180TurtleSim("red")Multiplier = 0.00012Degree = 45TurtleSim("blue")t.shapesize(0.1)plt.plot(data1, label="degr")plt.plot(data2, label="head")plt.plot(data3, label="x")plt.title("Position")plt.xlabel("Degree -90 to 90 ")plt.ylabel("Speed")plt.legend()plt.show()